import{z as B,x as l,o as E,c as n,q as r,j as t,D as e,d as A,s as i,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"硬件安全的视角","description":"","frontmatter":{"title":"硬件安全的视角","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-hardware-perspective.md","filePath":"cs/ss-hardware-perspective.md","lastUpdated":1791413859000}'),c={name:"cs/ss-hardware-perspective.md"};function h(p,a,d,m,C,T){const s=l("Mermaid");return E(),n("div",null,[a[2]||(a[2]=r('<h1 id="硬件安全的视角" tabindex="-1">硬件安全的视角 <a class="header-anchor" href="#硬件安全的视角" aria-label="Permalink to &quot;硬件安全的视角&quot;">​</a></h1><div class="epigraph"><p>ISA 是硬件写给软件的合同，微结构是没写进合同的行为；安全的麻烦从有人开始读合同的空白处开始。</p><footer>—— 据 Kocher et al., Spectre Attacks, 2019；Kim et al., Rowhammer, ISCA 2014 整理</footer></div><p><a href="/cs/ss-memory-safe-langs">上一课</a>把内存安全从运行时纪律改成编译期证明，但那份证明假设硬件是理想机——按 ISA 逐条忠实执行。本课把硬件请回舞台。主干已有<a href="/cs/transient-exec">瞬时执行</a>、<a href="/cs/spectre-mitigations">Spectre 缓解</a>、<a href="/cs/rowhammer-mitigations">Rowhammer 缓解</a>、<a href="/cs/flush-reload">Flush+Reload</a>、<a href="/cs/power-analysis-dpa">功耗分析 DPA</a>、<a href="/cs/secure-boot-chain">安全启动链</a>、<a href="/cs/firmware-security">固件安全</a>与<a href="/cs/pointer-authentication">指针认证</a>；缺口是一个统一视角：硬件同时是根信任的来源与新的攻击面，两份合同方向相反。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>作为防御，硬件提供了软件给不了的四样根：启动链把信任锚进 ROM 与一次性写入的密钥；TEE 把操作系统踢出敏感代码的 TCB；PAC/CET 把控制流完整性沉到硬件；内存标签把内存错误检测沉到访存路径。作为攻击面，同一批硬件自揭其短：微结构是 ISA 没写的行为——预测执行与缓存放大本为性能而生，却把「隔离」漏成信道（Spectre 类）；DRAM 的模拟行为被系统性扰动利用（Rowhammer 翻转比特）；物理接触下，功耗轨迹与故障注入是直接探针。缺口不是复述这些机制，而是给出读这份合同的层次与判据。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三个层次各读一段" tabindex="-1">三个层次各读一段 <a class="header-anchor" href="#三个层次各读一段" aria-label="Permalink to &quot;三个层次各读一段&quot;">​</a></h3><p>架构层：安全启动链从不可变的 ROM 代码出发逐级验签——信任有了根，代价是根不可热换，固件层的漏洞修补接回<a href="/cs/ss-supply-chain">供应链</a>的站点图。微结构层：判据是「性能优化的每一处共享，都是潜在信道」——缓存、TLB、分支预测器、执行端口，凡是被秘密影响时长的部件都能计时读出；缓解是隔离加栅栏，每道都带性能税（专课已算过账）。物理层：DPA 把密钥从功耗轨迹里统计出来，防御是掩蔽与噪声；故障注入让「跳过一次比较」成为可能，防御是冗余校验与随机化时序。新工具也在此层兑现：内存标签（MTE）按 16 字节粒度给内存打 4 位标签、指针高位携带期望值，访存不符即陷阱——把<a href="/cs/ss-memory-safe-langs">内存安全语言</a>一课证不掉的剩余内存类，变成确定性检测。</p>',8)),(E(),t(o,null,{default:e(()=>[i(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHYS%5B%22%E7%89%A9%E7%90%86%E5%B1%82%EF%BC%9ADPA%20%2F%20%E6%95%85%E9%9A%9C%E6%B3%A8%E5%85%A5%22%5D%20--%3E%20MICRO%5B%22%E5%BE%AE%E7%BB%93%E6%9E%84%E5%B1%82%EF%BC%9A%E7%9E%AC%E6%80%81%E6%89%A7%E8%A1%8C%20%2F%20%E7%BC%93%E5%AD%98%E4%BF%A1%E9%81%93%20%2F%20Rowhammer%22%5D%0A%20%20MICRO%20--%3E%20ARCH%5B%22%E6%9E%B6%E6%9E%84%E5%B1%82%EF%BC%9A%E5%90%AF%E5%8A%A8%E9%93%BE%20%2F%20TEE%20%2F%20PAC%20%2F%20MTE%22%5D%0A%20%20ARCH%20--%3E%20ROOT%5B%22%E9%98%B2%E5%BE%A1%EF%BC%9A%E4%BF%A1%E4%BB%BB%E6%9C%89%E6%A0%B9%EF%BC%8C%E8%B6%8A%E6%B2%89%E8%B6%8A%E5%BF%AB%22%5D%0A%20%20PHYS%20--%3E%20PROBE%5B%22%E6%94%BB%EF%BC%9A%E6%8E%A5%E8%A7%A6%E5%8D%B3%E6%8E%A2%E9%92%88%22%5D%0A%20%20MICRO%20--%3E%20LEAK%5B%22%E6%94%BB%EF%BC%9A%E5%85%B1%E4%BA%AB%E5%8D%B3%E4%BF%A1%E9%81%93%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">ARM MTE 的合同：内存按 16 字节粒度划分，4 位标签存于指针高位 unused 位，Load/Store 时硬件核对，不符即异常——use-after-free 与越界从概率攻击变成确定性的崩溃。据 ARM 架构手册整理。</span></p><p><span class="marginnote">4 位标签意味着每 16 字节内存块只有 16 种标签取值，赋错相邻标签的碰撞概率约 1/16——所以 MTE 能把绝大多数越界当场抓住，但不是 100% 拦截，工程上要按「大概率崩溃、小概率漏检」来评估它兜住多少风险。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么硬件漏洞最难收尾：不可热修，缓解只能在微码、固件与软件栅栏之间分摊，各有性能账；攻击面与性能同源——你关不掉缓存与预测执行，只能给共享加策略。信任的传递链是「ROM → 固件 → TEE → 应用」，任何一环失守都从根上折价，所以固件供应链是这条链上最现实的一环，也是与第 3 课的交点。反过来看，硬件缓解（PAC、MTE、CET）的加速比在于：软件里逐次检查的开销，沉到硬件路径后按每条指令摊销——这是「越沉越快」的机制，也是内存安全语言与硬件缓解互为表里的原因。</p><p><span class="marginnote">微码就是烧在 CPU 内部、把一条机器指令翻译成一串更细小微操作的固件——相当于芯片里可以更新的「解释器」。所以 Spectre 这类改不了电路的漏洞，厂商常以微码更新的形式打补丁：合同改不了，就改执行合同的方式。</span></p>',5)),(E(),t(o,null,{default:e(()=>[i(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROM%5B%22ROM%20%E6%A0%B9%E5%AF%86%E9%92%A5%E4%B8%8E%E9%A6%96%E6%AE%B5%E4%BB%A3%E7%A0%81%22%5D%20--%3E%7C%E9%AA%8C%E7%AD%BE%7C%20BL%5B%22Bootloader%22%5D%0A%20%20BL%20--%3E%7C%E9%AA%8C%E7%AD%BE%7C%20FW%5B%22%E5%9B%BA%E4%BB%B6%20%2F%20%E5%86%85%E6%A0%B8%22%5D%0A%20%20FW%20--%3E%7C%E9%9A%94%E7%A6%BB%E5%90%AF%E5%8A%A8%7C%20TEE%5B%22TEE%20%E5%AE%89%E5%85%A8%E4%B8%96%E7%95%8C%22%5D%0A%20%20TEE%20--%3E%7C%E6%8F%90%E4%BE%9B%E6%9C%8D%E5%8A%A1%7C%20APP%5B%22%E6%99%AE%E9%80%9A%E5%BA%94%E7%94%A8%22%5D%0A%20%20FW%20-.%E8%A2%AB%E6%8D%A2%E6%8E%89.-%3E%20FAKE%5B%22%E6%81%B6%E6%84%8F%E5%9B%BA%E4%BB%B6%E6%8E%A5%E7%AE%A1%E5%85%A8%E9%83%A8%E4%B8%8B%E6%B8%B8%22%5D%0A%20%20BL%20-.%E8%B7%B3%E8%BF%87%E9%AA%8C%E7%AD%BE.-%3E%20FAKE%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">信任链可以想象成一串连锁的信封：每个信封都由上一把钥匙封口，拆到哪一层，就知道前面没有被换过——但拆封的规则写死在第一层（ROM）里，第一层坏了后面全部作废。初学者容易以为固件被攻破只是「电脑变慢」，实际上攻击者从此拥有了比操作系统更高的权限。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Spectre、Rowhammer、Flush+Reload 的机制细节主干已有专课，本课不重讲；TEE 内部的调用约定与证明协议点到为止；硬件木马与逻辑级供应链攻击的检测不展开。物理攻击的实操配方不写，只写模型与防御对应。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬件同时是根信任与攻击面：启动链、TEE、PAC/CET、MTE 在防御侧，微结构与物理层在攻方。</li><li>判据：性能优化的每一处共享都是潜在信道；信任链任何一环失守都从根上折价。</li><li>硬件漏洞不可热修，缓解在微码、固件与软件栅栏间分摊，各有性能账。</li><li>MTE 把剩余内存类变成确定性检测，与安全语言互为表里；固件供应链是现实交点。</li><li>出处：Kocher et al., 2019；Kim et al., ISCA 2014；ARM 架构手册；对照 <a href="/cs/spectre-mitigations">spectre-mitigations</a>、<a href="/cs/rowhammer-mitigations">rowhammer-mitigations</a>。</li></ul>',5))])}const u=B(c,[["render",h]]);export{_ as __pageData,u as default};
